    private static void Add(Dictionary<string, ItemData.Def> all, ItemData.Def def)
    {
        // Фикс скрытой ошибки: поле Kind не заполнялось ни из JSON, ни в коде.
        def.Kind = ItemData.KindOf(def.Type);
        all[def.Key] = def;
    }
